// Rig dimensions and metadata only: no sail areas or polar values from either model database.
const aliases=s=>String(s||'').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().replace(/\bclub\s*swan/g,'clubswan').replace(/\biy(?=\s*\d)/g,'italia').replace(/\bgs(?=\s*\d)/g,'grand soleil').replace(/\biy\b/g,'italia').replace(/\bgs\b/g,'grand soleil').replace(/\bone\s*design\b/g,'od').replace(/\(\s*(?:19|20)\d{2}[^)]*\)/g,'');
export const rigModelKey=s=>aliases(s).replace(/\b(od|f|std|standard|club|beneteau|jeanneau)\b/g,'').replace(/[^a-z0-9]/g,'');
const digits=s=>(aliases(s).match(/\d+(?:[.,]\d+)?/g)||[]).map(x=>x.replace(/[.,]/g,'')).join(':');
export function metricLength(value){if(typeof value==='number')return Number.isFinite(value)&&value>0?value:null;const text=String(value??'').normalize('NFKC'),matches=[...text.matchAll(/(\d+(?:[.,]\d+)?)\s*m\b/gi)];if(matches.length)return Number(matches.at(-1)[1].replace(',','.'))||null;if(/^\s*\d+(?:[.,]\d+)?\s*$/.test(text))return Number(text.replace(',','.'))||null;return null;}
export function sailingRigRows(rows){return rows.map((r,index)=>({id:`sailing:${index}`,name:String(r.Model||''),version:String(r.Version||''),source:'sailing_database.json',sourceIndex:index,loa:metricLength(r['Hull length']),beam:metricLength(r['Beam (width)']),p:metricLength(r.P),e:metricLength(r.E),i:metricLength(r.I),j:metricLength(r.J),mastHeightDWL:metricLength(r['Mast height from DWL']),riggingType:String(r['Rigging type']||''),hullType:String(r['Hull type']||''),spreaders:Number(r['Number of levels of spreaders'])||null,spreaderAngle:/^\s*\d+(?:[.,]\d+)?\s*°/.test(String(r['Spreaders angle']))?Number(String(r['Spreaders angle']).replace('°','').replace(',','.').trim()):null}));}
export function validRig(r){return ['loa','p','e','i','j'].every(k=>typeof r[k]==='number'&&Number.isFinite(r[k])&&r[k]>0)&&r.p/r.loa>=.45&&r.p/r.loa<1.9&&r.i/r.loa>=.5&&r.i/r.loa<1.9&&r.e/r.loa>=.15&&r.e/r.loa<.85&&r.j/r.loa>=.15&&r.j/r.loa<.8&&(!r.hullType||r.hullType==='Monohull')&&(!r.riggingType||/sloop/i.test(r.riggingType));}
export function rigIndex(rows,newRows=[]){const normalized=[...rows.map(r=>({...r,source:r.source||'gold-boat.json'})),...sailingRigRows(newRows)],metadata=normalized.filter(r=>r.loa>0).map(r=>({...r,key:rigModelKey(r.name),numbers:digits(r.name)})),entries=metadata.filter(validRig),byKey=new Map();for(const r of entries){if(!byKey.has(r.key))byKey.set(r.key,[]);byKey.get(r.key).push(r);}return{entries,byKey,metadata};}
const areaFit=(boat,r,scale=1)=>Math.abs(Math.log(Math.max(.01,boat.areas.main/(r.p*r.e*scale*scale)/.62)));
function rigExtras(boat,r,metadata,scale){
 const key=rigModelKey(r.name),info=r.source==='sailing_database.json'?r:metadata.find(x=>x.source==='sailing_database.json'&&x.key===key&&Math.abs(x.loa/r.loa-1)<.12),P=r.p*scale,I=r.i*scale,J=r.j*scale,k=boat.length/10,riggingType=info?.riggingType||'',fractionMatch=riggingType.match(/(\d+)\s*\/\s*(\d+)/),fraction=fractionMatch?Number(fractionMatch[1])/Number(fractionMatch[2]):/masthead/i.test(riggingType)?1:/fractional/i.test(riggingType)?.92:null,mastHeight=info?.mastHeightDWL?info.mastHeightDWL*scale:null;
 const ISP=Math.max(I,P+.95*k,mastHeight?mastHeight-1*k:fraction?I/fraction:P+1.1*k),SPL=J,TPS=J+(boat.areas.gennaker>0?boat.length*.10:0);
 return{ISP,SPL,TPS,mastHeightDWL:mastHeight,riggingType:riggingType||'Sloop · armo ricostruito',spreaders:info?.spreaders||null,spreaderAngle:info?.spreaderAngle??null,sourceVersion:info?.version||'',metadataSource:info?.source||null,estimatedFields:['ISP','SPL','TPS'],estimates:{ISP:mastHeight?'Altezza albero da DWL meno quota stimata della coperta':fraction?'Rapporto di frazionamento del modello applicato a I':'Estensione stimata sopra P e altezza del boma',SPL:'Tangone assunto lungo J',TPS:boat.areas.gennaker>0?'J più bompresso stimato al 10% della lunghezza scafo':'Attacco a prua senza estensione di bompresso'}};
}
export function matchRig(boat,index){
 const plausible=(r,scale=1)=>{const ratio=boat.areas.main/(r.p*r.e*scale*scale);return ratio>=.28&&ratio<=.88;},key=rigModelKey(boat.model),numbers=digits(boat.model),preferNew=rows=>rows.some(r=>r.source==='sailing_database.json')?rows.filter(r=>r.source==='sailing_database.json'):rows;
 let matches=preferNew((index.byKey.get(key)||[]).filter(r=>Math.abs(r.loa/boat.length-1)<.12&&plausible(r))),type='model';
 if(!matches.length){type='compatible';matches=preferNew(index.entries.filter(r=>r.numbers===numbers&&key.length>=4&&r.key.length>=4&&(r.key.includes(key)||key.includes(r.key))&&Math.abs(r.loa/boat.length-1)<.10&&plausible(r)));}
 if(!matches.length){type='similar';const pool=index.entries.filter(r=>plausible(r,boat.length/r.loa)),distances=pool.map(r=>({r,d:Math.abs(Math.log(r.loa/boat.length))})),nearest=Math.min(...distances.map(x=>x.d));matches=preferNew(distances.filter(x=>x.d<=Math.max(.035,nearest+.01)).map(x=>x.r));}
 if(!matches.length)throw Error('Nessun armo utilizzabile nelle banche dati.');
 matches.sort((a,b)=>{const cost=r=>{const scale=type==='similar'?boat.length/r.loa:1,lp=boat.areas.genoa/(.509*.985*Math.hypot(r.i,r.j)*r.j*scale*scale),beam=r.beam?Math.abs(Math.log((r.beam*scale)/boat.beam)):0;const variant=/\bfuoriserie\b|\bf\b/i.test(boat.model)?'fuoriserie':/\bclub\b/i.test(boat.model)&&!/club\s*swan/i.test(boat.model)?'club':null,variantCost=variant&&r.version&&!r.version.toLowerCase().includes(variant)?.5:0;return variantCost+Math.abs(Math.log(r.loa/boat.length))*12+beam*2+areaFit(boat,r,scale)*.8+(type==='similar'?1.8*Math.log(Math.max(.01,lp)/1.2)**2:0);};return cost(a)-cost(b);});
 const r=matches[0],scale=type==='similar'?boat.length/r.loa:1;return{P:r.p*scale,E:r.e*scale,I:r.i*scale,J:r.j*scale,source:r.source,model:r.name,sourceId:r.id,sourceLoa:r.loa,scale,match:type,...rigExtras(boat,r,index.metadata||index.entries,scale)};
}
